-- Private immutable PDF hosting. Preparation does not grant public access or charge.
CREATE TABLE protected_document_hostings(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), document_id TEXT NOT NULL, document_sha256 TEXT NOT NULL CHECK(length(document_sha256)=64), duration_days INTEGER NOT NULL CHECK(duration_days IN (1,7,30)), token_hash TEXT NOT NULL UNIQUE CHECK(length(token_hash)=64), password_salt TEXT NOT NULL, password_verifier TEXT NOT NULL, sealed_secrets TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','active','expired','revoked')), created_at TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>created_at), activated_at TEXT, revoked_at TEXT, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,document_id) REFERENCES documents(organization_id,id));
CREATE UNIQUE INDEX protected_document_current ON protected_document_hostings(organization_id,document_id) WHERE status IN ('draft','active');
CREATE INDEX protected_document_expiry ON protected_document_hostings(status,expires_at);
CREATE TRIGGER immutable_protected_document BEFORE UPDATE ON protected_document_hostings WHEN NEW.id IS NOT OLD.id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.document_id IS NOT OLD.document_id OR NEW.document_sha256 IS NOT OLD.document_sha256 OR NEW.duration_days IS NOT OLD.duration_days OR NEW.token_hash IS NOT OLD.token_hash OR NEW.password_salt IS NOT OLD.password_salt OR NEW.password_verifier IS NOT OLD.password_verifier OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at OR (NEW.sealed_secrets IS NOT OLD.sealed_secrets AND NEW.sealed_secrets<>'') OR (OLD.status IN ('expired','revoked') AND NEW.status<>OLD.status) OR (OLD.status='active' AND NEW.status='draft') BEGIN SELECT RAISE(ABORT,'immutable_protected_document'); END;
CREATE TABLE protected_hosting_charges(organization_id TEXT NOT NULL REFERENCES welcome_credit_grants(organization_id), hosting_id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor=100), created_at TEXT NOT NULL, FOREIGN KEY(organization_id,hosting_id) REFERENCES protected_document_hostings(organization_id,id), FOREIGN KEY(organization_id,dispatch_id) REFERENCES dispatches(organization_id,id));
CREATE TRIGGER immutable_protected_hosting_charge BEFORE UPDATE ON protected_hosting_charges BEGIN SELECT RAISE(ABORT,'immutable_protected_hosting_charge'); END;
CREATE TRIGGER retained_protected_hosting_charge BEFORE DELETE ON protected_hosting_charges BEGIN SELECT RAISE(ABORT,'immutable_protected_hosting_charge'); END;
CREATE TABLE protected_document_sessions(token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=64), organization_id TEXT NOT NULL, hosting_id TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, FOREIGN KEY(organization_id,hosting_id) REFERENCES protected_document_hostings(organization_id,id));
CREATE INDEX protected_document_session_expiry ON protected_document_sessions(expires_at);
CREATE TABLE protected_document_attempts(scope_hash TEXT NOT NULL, window_start INTEGER NOT NULL, attempts INTEGER NOT NULL CHECK(attempts>0), PRIMARY KEY(scope_hash,window_start));
-- Hosting is a separately disclosed service: provider settlement never refunds it.
DROP VIEW welcome_credit_balances;
CREATE VIEW welcome_credit_balances AS SELECT g.organization_id,g.currency,g.amount_minor AS granted_minor,g.created_at AS granted_at,COALESCE((SELECT SUM(e.reserved_delta) FROM welcome_credit_entries e WHERE e.organization_id=g.organization_id),0) AS reserved_minor,COALESCE((SELECT SUM(e.spent_delta) FROM welcome_credit_entries e WHERE e.organization_id=g.organization_id),0)+COALESCE((SELECT SUM(h.amount_minor) FROM protected_hosting_charges h WHERE h.organization_id=g.organization_id),0) AS spent_minor,g.amount_minor-COALESCE((SELECT SUM(e.reserved_delta+e.spent_delta) FROM welcome_credit_entries e WHERE e.organization_id=g.organization_id),0)-COALESCE((SELECT SUM(h.amount_minor) FROM protected_hosting_charges h WHERE h.organization_id=g.organization_id),0) AS available_minor FROM welcome_credit_grants g;
CREATE TRIGGER protected_hosting_charge_guard BEFORE INSERT ON protected_hosting_charges BEGIN
 SELECT RAISE(ABORT,'protected_hosting_invalid') WHERE NOT EXISTS(SELECT 1 FROM protected_document_hostings h JOIN dispatches d ON d.organization_id=h.organization_id AND d.document_id=h.document_id JOIN approvals a ON a.organization_id=d.organization_id AND a.dispatch_id=d.id AND a.fingerprint=d.fingerprint WHERE h.id=NEW.hosting_id AND h.organization_id=NEW.organization_id AND h.status='draft' AND h.expires_at>NEW.created_at AND d.id=NEW.dispatch_id AND d.status='queued' AND d.mode='production' AND d.channel='email' AND a.expires_at>NEW.created_at AND json_extract(d.options_json,'$.emailDeliveryMode')='protected_link' AND json_extract(d.options_json,'$.protectedDocument.hostingId')=h.id AND json_extract(d.options_json,'$.protectedDocument.hostingFeeMinor')=100);
 SELECT RAISE(ABORT,'credit_exhausted') WHERE NOT EXISTS(SELECT 1 FROM welcome_credit_balances WHERE organization_id=NEW.organization_id AND available_minor>=100);
END;
CREATE TRIGGER protected_hosting_activated AFTER INSERT ON protected_hosting_charges BEGIN UPDATE protected_document_hostings SET status='active',activated_at=NEW.created_at WHERE organization_id=NEW.organization_id AND id=NEW.hosting_id AND status='draft'; END;
CREATE TRIGGER protected_hosting_acceptance_guard BEFORE UPDATE OF status ON dispatches WHEN OLD.status='prepared' AND NEW.status='queued' AND json_extract(NEW.options_json,'$.emailDeliveryMode')='protected_link' BEGIN
 SELECT RAISE(ABORT,'protected_hosting_invalid') WHERE NEW.mode<>'production' OR NEW.channel<>'email' OR NOT EXISTS(SELECT 1 FROM protected_document_hostings h JOIN documents doc ON doc.organization_id=h.organization_id AND doc.id=h.document_id WHERE h.organization_id=NEW.organization_id AND h.id=json_extract(NEW.options_json,'$.protectedDocument.hostingId') AND h.document_id=NEW.document_id AND h.document_sha256=doc.sha256 AND doc.status='ready' AND h.status IN ('draft','active') AND h.expires_at>NEW.updated_at AND h.expires_at=json_extract(NEW.options_json,'$.protectedDocument.expiresAt') AND h.duration_days=json_extract(NEW.options_json,'$.protectedDocument.durationDays') AND ((h.status='draft' AND json_extract(NEW.options_json,'$.protectedDocument.hostingFeeMinor')=100) OR (h.status='active' AND json_extract(NEW.options_json,'$.protectedDocument.hostingFeeMinor') IN (0,100))));
END;
CREATE TRIGGER protected_hosting_acceptance AFTER UPDATE OF status ON dispatches WHEN OLD.status='prepared' AND NEW.status='queued' AND NEW.mode='production' AND json_extract(NEW.options_json,'$.emailDeliveryMode')='protected_link' BEGIN
 INSERT INTO protected_hosting_charges(organization_id,hosting_id,dispatch_id,amount_minor,created_at) SELECT NEW.organization_id,h.id,NEW.id,100,NEW.updated_at FROM protected_document_hostings h WHERE h.organization_id=NEW.organization_id AND h.id=json_extract(NEW.options_json,'$.protectedDocument.hostingId') AND h.status='draft' AND NOT EXISTS(SELECT 1 FROM protected_hosting_charges c WHERE c.hosting_id=h.id);
 UPDATE usage SET reserved_minor=reserved_minor-json_extract(NEW.options_json,'$.protectedDocument.hostingFeeMinor'),confirmed_minor=confirmed_minor+COALESCE((SELECT amount_minor FROM protected_hosting_charges WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id),0) WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=substr(NEW.updated_at,1,7);
 UPDATE reservations SET amount_minor=amount_minor-json_extract(NEW.options_json,'$.protectedDocument.hostingFeeMinor') WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND status='reserved';
END;
-- A live paid hosting term protects the exact original from the existing age purge.
CREATE TRIGGER protected_document_retention BEFORE UPDATE OF status ON documents WHEN NEW.status='purged' AND EXISTS(SELECT 1 FROM protected_document_hostings h WHERE h.organization_id=OLD.organization_id AND h.document_id=OLD.id AND h.status='active' AND h.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(IGNORE); END;

-- Reserve only transport after the separate hosting service is charged atomically.
DROP TRIGGER welcome_credit_reservation_guard;
CREATE TRIGGER welcome_credit_reservation_guard BEFORE INSERT ON welcome_credit_reservations BEGIN
 SELECT RAISE(ABORT,'credit_reservation_invalid') WHERE NEW.status<>'reserved' OR NOT EXISTS(SELECT 1 FROM dispatches WHERE organization_id=NEW.organization_id AND id=NEW.dispatch_id AND mode='production' AND status='queued' AND currency='EUR' AND ceiling_minor-(iif(json_extract(options_json,'$.emailDeliveryMode')='protected_link',COALESCE(json_extract(options_json,'$.protectedDocument.hostingFeeMinor'),0),0))=NEW.amount_minor AND estimated_minor-(iif(json_extract(options_json,'$.emailDeliveryMode')='protected_link',COALESCE(json_extract(options_json,'$.protectedDocument.hostingFeeMinor'),0),0))=NEW.charge_minor);
 SELECT RAISE(ABORT,'credit_exhausted') WHERE NOT EXISTS(SELECT 1 FROM welcome_credit_balances WHERE organization_id=NEW.organization_id AND available_minor>0 AND available_minor>=NEW.amount_minor);
END;
DROP TRIGGER welcome_credit_accept;
CREATE TRIGGER welcome_credit_accept AFTER UPDATE OF status ON dispatches WHEN OLD.status='prepared' AND NEW.status='queued' AND NEW.mode='production' BEGIN INSERT INTO welcome_credit_reservations(organization_id,dispatch_id,amount_minor,charge_minor,status,created_at,updated_at) VALUES(NEW.organization_id,NEW.id,NEW.ceiling_minor-(iif(json_extract(NEW.options_json,'$.emailDeliveryMode')='protected_link',COALESCE(json_extract(NEW.options_json,'$.protectedDocument.hostingFeeMinor'),0),0)),NEW.estimated_minor-(iif(json_extract(NEW.options_json,'$.emailDeliveryMode')='protected_link',COALESCE(json_extract(NEW.options_json,'$.protectedDocument.hostingFeeMinor'),0),0)),'reserved',NEW.updated_at,NEW.updated_at); END;

-- Transport quotes retain the immutable referenced PDF but contain zero attached bytes in link mode.
DROP VIEW valid_live_delivery_quotes;
CREATE VIEW valid_live_delivery_quotes AS SELECT q.*,p.valid_from AS policy_valid_from,p.expires_at AS policy_expires_at FROM live_delivery_quotes q JOIN dispatches d ON d.organization_id=q.organization_id AND d.id=q.dispatch_id JOIN trusted_delivery_costs p ON p.organization_id=q.organization_id AND p.id=q.policy_id JOIN senders s ON s.organization_id=d.organization_id AND s.id=d.sender_id LEFT JOIN documents doc ON doc.organization_id=d.organization_id AND doc.id=d.document_id WHERE (json_extract(d.options_json,'$.emailDeliveryMode') IS NOT 'protected_link' OR EXISTS(SELECT 1 FROM protected_document_hostings h WHERE h.organization_id=d.organization_id AND h.id=json_extract(d.options_json,'$.protectedDocument.hostingId') AND h.document_id=d.document_id AND h.document_sha256=doc.sha256 AND h.status IN ('draft','active') AND h.expires_at=json_extract(d.options_json,'$.protectedDocument.expiresAt') AND h.duration_days=json_extract(d.options_json,'$.protectedDocument.durationDays') AND h.expires_at>q.created_at AND json_extract(d.options_json,'$.protectedDocument.hostingFeeMinor') IN (0,100) AND (h.status='active' OR json_extract(d.options_json,'$.protectedDocument.hostingFeeMinor')=100))) AND (d.provider IS NULL OR d.provider=q.provider) AND d.mode='production' AND d.channel=q.channel AND d.quote_fingerprint=q.fingerprint AND d.fingerprint=q.dispatch_fingerprint AND p.status='qualified' AND p.sender_id=d.sender_id AND p.channel=d.channel AND p.provider=q.provider AND p.account_id=q.account_id AND p.route_id=q.route_id AND s.status='verified' AND s.mode='production' AND s.channel=d.channel AND s.address=d.sender_address AND (d.document_id IS NULL OR (doc.status='ready' AND doc.sha256=json_extract(q.input_json,'$.documentSha256'))) AND q.attachment_bytes=iif(json_extract(d.options_json,'$.emailDeliveryMode')='protected_link',0,COALESCE(doc.size,0)) AND q.amount_minor+(iif(json_extract(d.options_json,'$.emailDeliveryMode')='protected_link',COALESCE(json_extract(d.options_json,'$.protectedDocument.hostingFeeMinor'),0),0))=d.estimated_minor AND q.ceiling_minor=d.ceiling_minor AND q.currency=d.currency AND q.source_reference=p.source_reference AND q.source_sha256=p.source_sha256 AND q.fiscal_basis=p.pricing_basis AND (p.pricing_basis='qualified_final_variable_cost' OR (json_extract(q.input_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(q.input_json,'$.fx.numerator')=json_extract(p.rate_json,'$.eurPerUsdNumerator') AND json_extract(q.input_json,'$.fx.denominator')=json_extract(p.rate_json,'$.eurPerUsdDenominator') AND json_extract(q.input_json,'$.fx.date')=json_extract(p.rate_json,'$.fxDate') AND json_extract(q.input_json,'$.fx.source')=json_extract(p.rate_json,'$.fxSource') AND p.channel='email') OR (p.pricing_basis='public_list_price_ex_tax' AND p.channel='postal' AND p.provider='pingen' AND p.account_id=p.route_id AND p.base_numerator=0 AND p.byte_numerator=0 AND p.rate_denominator=1 AND json_type(p.rate_json)='object' AND (SELECT count(*) FROM json_each(p.rate_json))=8 AND json_extract(p.rate_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(p.rate_json,'$.method')='pingen_price_calculator' AND json_extract(p.rate_json,'$.currency')='EUR' AND json_extract(p.rate_json,'$.unit')='letter' AND json_extract(p.rate_json,'$.tariffSource')='https://api.pingen.com/documentation/swagger-docs' AND json_extract(p.rate_json,'$.taxBasis')='shipping_price_excluding_vat' AND json_extract(p.rate_json,'$.taxSource')='https://help.pingen.com/en/credits-and-billing/introduction-balance-and-credits' AND json_type(p.rate_json,'$.tariffDate')='text' AND length(json_extract(p.rate_json,'$.tariffDate'))=10 AND json_extract(p.rate_json,'$.tariffDate')=date(json_extract(p.rate_json,'$.tariffDate'),'+0 days') AND json_extract(p.rate_json,'$.tariffDate')<=substr(p.valid_from,1,10) AND json_extract(p.options_json,'$.addressPosition') IN ('left','right') AND json_extract(p.options_json,'$.deliveryProduct') IN ('cheap','fast') AND json_extract(p.options_json,'$.printMode') IN ('simplex','duplex') AND json_extract(p.options_json,'$.printSpectrum') IN ('grayscale','color') AND p.options_json=json_object('addressPosition',json_extract(p.options_json,'$.addressPosition'),'deliveryProduct',json_extract(p.options_json,'$.deliveryProduct'),'printMode',json_extract(p.options_json,'$.printMode'),'printSpectrum',json_extract(p.options_json,'$.printSpectrum')) AND json_extract(q.input_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_type(q.input_json,'$.fx') IS NULL)) AND q.expires_at<=p.expires_at AND q.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ',q.created_at,'+'||p.quote_ttl_seconds||' seconds') AND json_extract(q.input_json,'$.channel') IS d.channel AND json_extract(q.input_json,'$.recipient') IS d.recipient_json AND json_extract(q.input_json,'$.documentId') IS d.document_id AND json_extract(q.input_json,'$.senderId') IS d.sender_id AND json_extract(q.input_json,'$.senderAddress') IS d.sender_address AND json_extract(q.input_json,'$.subject') IS d.subject AND json_extract(q.input_json,'$.html') IS d.html AND json_extract(q.input_json,'$.text') IS d.text AND json_extract(q.input_json,'$.options') IS d.options_json AND json_extract(q.input_json,'$.campaignId') IS d.campaign_id AND json_extract(q.input_json,'$.estimatedMinor') IS d.estimated_minor AND json_extract(q.input_json,'$.ceilingMinor') IS d.ceiling_minor AND json_extract(q.input_json,'$.currency') IS d.currency AND json_extract(q.input_json,'$.mode') IS d.mode AND ((d.channel='email' AND (json_extract(p.rate_json,'$.attachmentBasis')='raw_pdf_bytes' OR (p.provider='resend' AND json_extract(p.rate_json,'$.attachmentBasis')='included_pdf' AND p.byte_numerator=0) OR (json_extract(p.rate_json,'$.attachmentBasis')='no_attachments' AND (d.document_id IS NULL OR json_extract(d.options_json,'$.emailDeliveryMode')='protected_link') AND q.attachment_bytes=0 AND p.byte_numerator=0 AND json_type(p.rate_json,'$.usdMicrosPerGb') IS NULL AND json_type(p.rate_json,'$.bytesPerGb') IS NULL)) AND (p.options_json=d.options_json OR (p.provider='resend' AND p.options_json='{}')) AND q.provider_draft_id IS NULL AND q.prepared_letter_id IS NULL AND q.supplier_numerator=CAST(p.base_numerator+p.byte_numerator*q.attachment_bytes AS TEXT) AND q.supplier_denominator=CAST(p.rate_denominator AS TEXT) AND q.supplier_nanoeur=(p.base_numerator+p.byte_numerator*q.attachment_bytes+p.rate_denominator-1)/p.rate_denominator AND q.evidence_sha256=p.source_sha256) OR (d.channel='postal' AND doc.id IS NOT NULL AND q.supplier_nanoeur%10000000=0 AND q.supplier_numerator=CAST(q.supplier_nanoeur AS TEXT) AND q.supplier_denominator='1' AND EXISTS(SELECT 1 FROM provider_drafts pd WHERE pd.organization_id=d.organization_id AND pd.id=q.provider_draft_id AND pd.provider='pingen' AND pd.status='prepared' AND pd.provider_id=q.prepared_letter_id AND pd.document_id=doc.id AND pd.document_sha256=doc.sha256 AND pd.sender_id=s.id AND pd.sender_address=s.address AND pd.recipient_json=d.recipient_json AND pd.options_json=p.options_json AND pd.ceiling_minor=d.ceiling_minor AND pd.currency=d.currency AND (pd.claimed_dispatch_id IS NULL OR pd.claimed_dispatch_id=d.id) AND json_extract(d.options_json,'$.providerDraftId')=pd.id AND json_extract(d.options_json,'$.preparedLetterId')=pd.provider_id AND json_extract(d.options_json,'$.expectedAddress')=pd.expected_address AND json_extract(d.options_json,'$.addressPosition')=json_extract(pd.options_json,'$.addressPosition') AND json_extract(d.options_json,'$.deliveryProduct')=json_extract(pd.options_json,'$.deliveryProduct') AND json_extract(d.options_json,'$.printMode')=json_extract(pd.options_json,'$.printMode') AND json_extract(d.options_json,'$.printSpectrum')=json_extract(pd.options_json,'$.printSpectrum'))));
